// A server package in the style of the common Node routers: `server()`
// makes an app, `get` registers a route on it, and `mount` serves a child
// app's routes under a prefix.
export interface Request {
  url: string;
}

export interface Reply {
  send(body: unknown): void;
}

export type Handler = (request: Request, reply: Reply) => unknown;

export interface App {
  get(path: string, handler: Handler): App;
  /** Serves `child`'s routes under `prefix`. */
  mount(prefix: string, child: App): App;
  listen(port: number): void;
}

export declare function server(): App;
